  "plan": "Edit /app/pipeline/report.py to implement build_site_summary(records) that: 1) groups by site, 2) filters sensors with status "ok", 3) flattens non-null readings, 4) counts sensors and readings, 5) computes mean and max as floats with 2-decimal formatting handled later in write_csv. Then run the pipeline.",
  "commands": [
    {
      "keystrokes": "cat > /app/pipeline/report.py <<'EOF'
"""Site-level summary report."""
import csv

FIELDS = ["site", "sensors", "readings", "mean_value", "max_value"]


def build_site_summary(records):
    """Aggregate sensor records into one row per site.

    - Only sensors with status "ok" count.
    - Null readings are ignored.
    - Return a list of dicts, one per site, sorted by site name.
    - Each dict has keys: site, sensors, readings, mean_value, max_value.
      mean_value and max_value are floats.
    """
    # Group sensors by site
    site_to_sensors = {}
    for rec in records:
        site = rec.get("site")
        sensor_id = rec.get("sensor_id")
        status = rec.get("status")
        if status != "ok":
            continue
        if site not in site_to_sensors:
            site_to_sensors[site] = []
        # Add all non-null readings from this sensor
        for reading in rec.get("readings", []):
            val = reading.get("value")
            if val is not None:
                site_to_sensors[site].append(float(val))

    # Build rows for each site
    rows = []
    for site in sorted(site_to_sensors.keys()):
        readings_list = site_to_sensors[site]
        row = {
            "site": site,
            "sensors": 0,
            "readings": len(readings_list),
            "mean_value": 0.0,
            "max_value": 0.0
        }
        if readings_list:
            row["sensors"] = len(readings_list)  # number of readings (values)
            row["mean_value"] = sum(readings_list) / len(readings_list)
            row["max_value"] = max(readings_list)
        rows.append(row)
    return rows


def write_csv(rows, path):
    with open(path, "w", newline="") as fh:
        w = csv.writer(fh)
        w.writerow(FIELDS)
        for r in rows:
            w.writerow([r["site"], r["sensors"], r["readings"],
                        f"{r['mean_value']:.2f}", f"{r['max_value']:.2f}"])
EOF
