#!/bin/bash
# Daily signup rollup for the growth dashboard.
# Usage: rollup.sh [EVENTS_DIR] [OUT_CSV]
tset -euo pipefail

dir=${1:-/data/events}
out=${2:-/app/out/signups_by_plan.csv}
mkdir -p "$(dirname "$out")"

# Temporary file for deduplicated signups
tmp=$(mktemp)

# Process every regular file in the directory
for f in "$dir"/*; do
  # Process .jsonl files
  if [[ "$f" == *.jsonl && -f "$f" ]]; then
    jq -c 'select(.type == "signup") | {event_id, plan: (.account // .plan), user_id: (.user.id // .user_id)}' "$f" >> "$tmp"
  # Process .jsonl.gz files
  elif [[ "$f" == *.jsonl.gz && -f "$f" ]]; then
    zcat "$f" | jq -c 'select(.type == "signup") | {event_id, plan: (.account // .plan), user_id: (.user.id // .user_id)}' >> "$tmp"
  fi
done

# Use awk to count unique event_ids per plan and unique users
awk -F'[,:}]' '
  # Parse each line from tmp file
  {
    # Extract fields from the JSON snippet in $0
    match($0, /"event_id":"([^"]+)"/, e);
    match($0, /"plan":"([^"]+)"/, p);
    match($0, /"user_id":"([^"]+)"/, u);

    event_id = e[1];
    plan = p[1];
    user_id = u[1];

    # Count only unique event_id per plan
    if (!(event_id "|" plan in seen_event[plan])) {
      seen_event[plan][event_id] = 1;
      count[plan]++;
      user_key = plan "|" user_id;
      if (!(user_key in seen_user)) {
        seen_user[user_key] = 1;
        users[plan]++;
      }
    }
  }
  END {
    # Output CSV header
    print "plan,signups,unique_users";
    # Sort by signups descending, then plan ascending
    n = asorti(count, plans, "@val_num_desc");
    for (i = 1; i <= n; i++) {
      p = plans[i];
      printf "%s,%d,%d\n", p, count[p], users[p];
    }
  }
' "$tmp" > "$out"

# Cleanup
rm -f "$tmp"
EOF
